function newProject() {
  modal('Create a project',projectForm(null),'Create project',async form => {const data=projectPayload(form);const result=await api('/projects',data);const p=result.project || result;state.cache={};if(p.id)location.hash=href(p.id);toast('Project created. Generate a roadmap or add your first task.');});
}
function projectPayload(form) {
  let checks;try{checks=JSON.parse(form.get('checks'));}catch{throw Error('Check commands must be valid JSON.');}
  if(!Array.isArray(checks)||checks.some(c=>!Array.isArray(c)||!c.length||c.some(a=>typeof a!=='string')))throw Error('Checks must be an array of nonempty argument arrays.');
  let commands;try{commands=JSON.parse(form.get('commands') || '[]');}catch{throw Error('Permitted commands must be valid JSON.');}
  if(!Array.isArray(commands)||commands.some(c=>!Array.isArray(c)||!c.length||c.some(a=>typeof a!=='string')))throw Error('Commands must be arrays of exact command arguments.');
  return {name:form.get('name'),brief:form.get('brief'),model:form.get('model'),checks,max_steps:Number(form.get('max_steps')),max_attempts:Number(form.get('max_attempts')),autonomy:form.has('autonomy'),auto_resume:form.has('auto_resume'),max_runtime:Number(form.get('max_runtime')),max_tokens:Number(form.get('max_tokens')),context:Number(form.get('context')),commands,memory:form.get('memory') || ''};
}
