function editTask(id) {const t=state.data.tasks.find(t=>t.id===Number(id));if(!t)return;modal(`Issue #${t.id}`,taskForm(t),'Save issue',async form=>{await api(`/tasks/${t.id}`,taskPayload(form));toast('Issue updated.');});bindCandidates();}
