    const t=state.data.tasks.find(t=>t.id===Number(id));modal('Accept completed work',`<p class="subtitle">Accept issue #${id}: ${esc(t?.title)}?</p><p class="hint">Confirm you reviewed the changes and any verification evidence. This records your acceptance.</p>`,'Accept work',async()=>{await api(`/tasks/${id}`,{status:'accepted'});toast('Work accepted.');});
