async function loadDiff(force=false,revision) {const p=currentProject();if(!p)return;const c=state.cache[p.id] ||= {};if(revision!==undefined)c.diffRevision=revision;if(c.diff!==undefined&&!force)return;const query=new URLSearchParams();if(c.diffTask)query.set('task_id',c.diffTask);else if(c.diffRevision)query.set('revision',c.diffRevision);const result=await api(`/projects/${p.id}/diff${query.size?'?'+query:''}`);c.diff=result.diff ?? result;shell();}
