async function loadTab() {
  if(state.route.page==='execution'){try{await loadExecution();}catch(ex){toast(ex.message,true);}return;}
  if(state.route.page==='analyst'){try{await loadAnalyst();}catch(ex){toast(ex.message,true);}return;}
  if(state.route.page==='team'){try{await loadTeam();}catch(ex){toast(ex.message,true);}return;}
  try {if(state.route.page==='evaluations'){await loadEvaluations();return;}if(state.route.page==='assistant'){await loadAssistant();return;}if(state.route.page==='health'){await loadHealth();return;}if(state.route.page!=='project')return;if(state.route.tab==='files')await loadFiles();else if(state.route.tab==='history')await loadHistory();else if(state.route.tab==='changes')await loadDiff();else if(state.route.tab==='company')await loadCompany();else if(state.route.tab==='sessions')await loadSessions();else if(state.route.tab==='chat')await loadMessages();}catch(ex){toast(ex.message,true);}
}
async function loadCompany(force=false) {const p=currentProject();if(!p)return;const c=state.cache[p.id] ||= {},result=await api(`/projects/${p.id}/company`);if(force||JSON.stringify(c.company)!==JSON.stringify(result.messages)){c.company=result.messages || [];shell();}}
async function loadSessions(force=false) {const p=currentProject();if(!p)return;const c=state.cache[p.id] ||= {},result=await api(`/projects/${p.id}/sessions`);if(force||JSON.stringify(c.sessions)!==JSON.stringify(result.sessions)){c.sessions=result.sessions || [];shell();}}
async function loadAssistant(force=false) {const result=await api('/assistant');if(force||JSON.stringify(state.assistantMessages)!==JSON.stringify(result.messages)){state.assistantMessages=result.messages || [];shell();const el=$('#assistant-messages');if(el)el.scrollTop=el.scrollHeight;}}
async function loadHealth(force=false) {const result=await api('/health');if(force||JSON.stringify(state.health)!==JSON.stringify(result)){state.health=result;shell();}}
async function refresh(force=false) {
  if(!state.authenticated||state.loading)return;
  state.loading=true;
  try {
    const previous=state.data.operations || [], result=await api('/state');
    state.data={projects:[],tasks:[],events:[],runs:[],settings:{},operations:[],...result};state.csrf=result.csrf || state.csrf;
    for(const o of state.data.operations || []) {
      const old=previous.find(p=>p.id===o.id);
      if(old && old.status!==o.status && ['failed','error'].includes(o.status))toast(o.error || `${o.kind} failed. See project activity.`,true);
      if(old && old.status!==o.status && ['done','completed','succeeded'].includes(o.status))toast(`${o.kind === 'plan'?'Roadmap':o.kind === 'check'?'Check results':'Assistant response'} ready.`);
      if(o.kind==='screenshot' && ['done','completed','succeeded','failed'].includes(o.status)){
        const c=state.cache[o.project_id] ||= {};if(c.screenshotPending){c.screenshotPending=false;if(o.status!=='failed')c.screenshotReady=Date.now();}
      }
    }
    const signature=JSON.stringify(state.data);
    const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('#dialog').open;
    if(force || (!editing && signature!==lastRender)) {lastRender=signature;shell();await loadTab();}
    else if(!editing){if(state.route.tab==='chat')await loadMessages();else if(state.route.tab==='company')await loadCompany();else if(state.route.page==='assistant')await loadAssistant();}
  } catch(ex){if(state.authenticated)toast(ex.message,true);}finally{state.loading=false;}
}
