async function downloadArchive(path,filename,body) {const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrf},...(body===undefined?{}:{body:JSON.stringify(body)})});if(!response.ok){const data=await response.json();throw Error(data.error || 'Download failed.');}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function importProject() {modal('Import an existing project','<p class="hint">Upload a source ZIP to create a new local repository. Git metadata and unsafe paths are rejected. Compressed size is limited to 20 MB.</p><div class="field"><label for="import-name">Project name</label><input id="import-name" name="name" maxlength="100" required></div><div class="field"><label for="import-brief">Project brief</label><textarea id="import-brief" name="brief" placeholder="What should the team do with this project?"></textarea></div><div class="field"><label for="import-file">Source archive</label><input id="import-file" name="archive" type="file" accept=".zip,application/zip" required></div>','Import project',async form=>{const file=form.get('archive');if(!file||file.size>20*1024*1024)throw Error('Choose a ZIP archive no larger than 20 MB.');const archive=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read that archive.'));reader.readAsDataURL(file);});const result=await api('/projects/import',{name:form.get('name'),brief:form.get('brief'),archive});const p=result.project || result;toast('Project imported into a new local repository.');location.hash=href(p.id);});}
async function action(name) {
  const p=currentProject();
  if(name==='refresh-execution'){await loadExecution(true);return;}
  if(name==='more-execution'){await loadExecution(true,true);return;}
  if(name==='refresh-analyst'){await loadAnalyst(true);return;}
  if(name==='idle-approval'&&p){await api(`/projects/${p.id}/idle-approval`,{approved:!p.idle_approved});toast(p.idle_approved?'Idle maintenance approval revoked.':'Queued maintenance approved for idle execution.');await refresh(true);return;}
  if(name==='refresh-team'){await loadTeam(true);return;}
  if(name==='new-skill'){editTeamSkill();return;}
  if(name==='menu'){$('#sidebar').classList.toggle('open');return;}
  if(name==='new-project'){newProject();return;}
  if(name==='import-project'){importProject();return;}
  if(name==='refresh-health'){await loadHealth(true);return;}
  if(name==='backup'){await downloadArchive('/backup','The-Workshop-backup.zip',{});toast('Workshop backup downloaded.');return;}
  if(name==='refresh-sessions'){await loadSessions(true);return;}
  if(name==='reload-preview'){const frame=$('#project-preview');if(frame)frame.src=frame.src;return;}
  if(name==='capture-preview'){const c=state.cache[p.id] ||= {};await api(`/projects/${p.id}/screenshot`,{path:c.previewPath || 'index.html',width:1280,height:900});c.screenshotPending=true;toast('Screenshot capture started.');await refresh(true);return;}
  if(name==='new-evaluation'){await newEvaluation();return;}
  if(name==='refresh-evaluations'){await loadEvaluations(true);return;}
  if(name==='project-settings'){editProject();return;}
  if(name==='new-task'){newTask();return;}
  if(name==='logout'){await api('/logout',{});state.authenticated=false;state.csrf='';renderLogin();return;}
  if(name==='models'){
    const form=$('#settings-form'),r=$('#connection-result');
    r.textContent='Connecting to Ollama…';r.className='connection';
    try {await api('/settings',settingsPayload(form));const result=await api('/models');state.models=result.models || result;const names=state.models.map(m=>m.name || m.model);r.textContent=names.length?`Connected · ${names.length} installed model${names.length===1?'':'s'}: ${names.join(', ')}`:'Connected, but no models are installed. Download a model in Ollama.';r.classList.add('good');$('#model-list').innerHTML=names.map(n=>`<option value="${esc(n)}"></option>`).join('');if(!$('#model').value&&names.length)$('#model').value=names[0];}catch(ex){r.textContent=ex.message;throw ex;}return;
  }
  if(!p)return;
  if(name==='download'){
    const response=await fetch(`/api/projects/${p.id}/download`,{credentials:'same-origin'});
    if(!response.ok){const result=await response.json();throw Error(result.error || 'Download failed.');}
    const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download=p.name.replace(/[^a-z0-9-]/gi,'-')+'.zip';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);return;
  }
  if(name==='start'){await api(`/projects/${p.id}/status`,{status:'running'});toast('Project started. The worker will process queued tasks.');await refresh(true);}
  if(name==='pause'){await api(`/projects/${p.id}/status`,{status:'paused'});toast('Pause requested. The current model call may finish before the worker stops.');await refresh(true);}
  if(name==='run-checks'){await api(`/projects/${p.id}/check`,{});toast('Acceptance checks started. Results will appear in Activity and Run history.');await refresh(true);}
  if(name==='plan'){modal('Generate a roadmap',`<p class="subtitle">The manager will turn the current project brief into an ordered task queue.</p><p class="hint">${tasksFor(p.id).length ? 'New tasks will be added to the existing queue. Review the result for overlap before starting.':'Review the resulting tasks and acceptance criteria before starting work.'}</p>`,'Generate roadmap',async()=>{await api(`/projects/${p.id}/plan`,{});toast('Planning started. You can keep browsing.');});}
  if(name==='refresh-files')await loadFiles(true);
  if(name==='refresh-history')await loadHistory(true);
  if(name==='refresh-diff')await loadDiff(true);
  if(name==='working-diff'){delete state.cache[p.id].diffTask;await loadDiff(true,'');}
  if(name==='checkpoint'){modal('Save a checkpoint','<div class="field"><label for="checkpoint-message">Describe this version</label><input id="checkpoint-message" name="message" placeholder="What changed?" maxlength="200" required></div>','Save checkpoint',async f=>{await api(`/projects/${p.id}/checkpoint`,{message:f.get('message')});delete state.cache[p.id];toast('Checkpoint saved.');});}
}
function restore(revision) {const p=currentProject();modal('Restore this version',`<div class="notice amber">Pause project work before restoring. This replaces current project files with the selected version and saves a new checkpoint.</div><p class="mono">${esc(revision)}</p><p class="hint">Review and checkpoint any current work you want to preserve first. Git history remains available.</p>`,'Restore version',async()=>{await api(`/projects/${p.id}/restore`,{revision});delete state.cache[p.id];toast('Version restored as a new checkpoint.');},{danger:true});}
async function sendChat(e) {
  e.preventDefault();const p=currentProject(),input=$('#chat-input'),message=input.value.trim();if(!message||chatSending)return;
  chatSending=true;input.value='';$('button',e.target).disabled=true;
  try {await api(`/projects/${p.id}/chat`,{message});await refresh(true);await loadMessages(true);}catch(ex){toast(ex.message,true);input.value=message;}finally{chatSending=false;await refresh(true);}
}
window.addEventListener('hashchange',async()=>{readRoute();window.scrollTo(0,0);if(state.authenticated){shell();await loadTab();}});
document.addEventListener('click',e=>{if(innerWidth<=760&&!e.target.closest('#sidebar')&&!e.target.closest('[data-action=menu]'))$('#sidebar')?.classList.remove('open');});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
(async()=>{readRoute();try{const s=await api('/session');state.csrf=s.csrf || '';state.authenticated=s.authenticated;if(state.authenticated)await refresh(true);else renderLogin();}catch{renderLogin();}pollTimer=setInterval(()=>{if(!document.hidden)refresh();},4000);})();
